{"source": "def _receipts(acquire):
    return acquire("history")

def _family():
    puts = ["ignore", "replace", "upsert"]
    channels = ["changes", "total", "both"]
    triggers = [False, True]
    out = []
    for p in puts:
        for c in channels:
            for t in triggers:
                out.append((p, c, t))
    return out

def _apply_put(items, key, value, mode):
    if key in items:
        if mode == "ignore":
            return 0
        items[key] = value
        return 1
    items[key] = value
    return 1

def _simulate(actions, mode, channel, trigger):
    items = {}
    main_changes = 0
    main_total = 0
    other_total = 0
    for a in actions:
        op = a.get("op")
        conn = a.get("connection", "main")
        if op == "put":
            n = _apply_put(items, a["key"], a["value"], mode)
            if conn == "main":
                main_changes = n
                main_total += n
            else:
                other_total += n
        elif op == "update":
            k = a["key"]
            if k in items:
                items[k] = a["value"]
                n = 1
            else:
                n = 0
            if conn == "main":
                main_changes = n
                main_total += n
            else:
                other_total += n
        elif op == "delete":
            k = a["key"]
            if k in items:
                del items[k]
                n = 1
            else:
                n = 0
            if conn == "main":
                main_changes = n
                main_total += n
            else:
                other_total += n
    if channel == "changes":
        ch = main_changes
    elif channel == "total":
        ch = main_total
    else:
        ch = main_total + other_total
    return ch, len(items), sum(items.values())

def _consistent(receipts, mode, channel, trigger):
    for r in receipts:
        ch, cnt, sm = _simulate(r["actions"], mode, channel, trigger)
        o = r["observed"]
        if ch != o["channel"] or cnt != o["committed_count"] or sm != o["committed_sum"]:
            return False
    return True

def _infer(receipts):
    good = []
    for p, c, t in _family():
        if _consistent(receipts, p, c, t):
            good.append((p, c, t))
    return good

def _predict(good, actions, goal):
    vals = set()
    for p, c, t in good:
        ch, cnt, sm = _simulate(actions, p, c, t)
        if goal == "channel":
            vals.add(ch)
        elif goal == "committed_count":
            vals.add(cnt)
        else:
            vals.add(sm)
    if len(vals) == 1:
        return list(vals)[0]
    return None

def investigate(context, acquire):
    receipts = _receipts(acquire)
    good = _infer(receipts)
    v = _predict(good, context["actions"], context["goal"])
    if v is None:
        return {"value": None, "unresolved": True}
    return {"value": v, "unresolved": False}

def transition(state, action, context, acquire):
    if state is None:
        good = _infer(_receipts(acquire))
        state = {"good": good, "actions": []}
    state["actions"].append(action)
    return state

def readout(state, context, acquire):
    if state is None:
        good = _infer(_receipts(acquire))
        actions = []
    else:
        good = state["good"]
        actions = state["actions"]
    v = _predict(good, actions, context["goal"])
    if v is None:
        return {"value": None, "unresolved": True}
    return {"value": v, "unresolved": False}
